// src/parts/filters.ts
function filterBar(controls, busy = false) {
  return b2`
    <div class="filter-gap"></div>
    <div class="filter-bar ${busy ? "busy" : ""}" role="toolbar" aria-label="Filter">
      ${controls}
    </div>
  `;
}
function filterSelect(label, value, options, onChange) {
  const chosen = options.find(([id]) => id === value) ?? options[0];
  return b2`
    <label class="filter-chip filter-select ${chosen === options[0] ? "" : "active"}">
      <span>${chosen[2] ?? chosen[1]}</span>
      <ha-icon icon="mdi:chevron-down"></ha-icon>
      <select
        aria-label=${label}
        @change=${(ev) => onChange(ev.target.value)}
      >
        ${options.map(
    ([id, text]) => b2`<option value=${id} ?selected=${id === chosen[0]}>${text}</option>`
  )}
      </select>
    </label>
  `;
}
function teamButton(ctx, picker, clubs, chosen) {
  const picked = clubs.filter((club) => chosen.includes(club.key));
  const names = picked.map((club) => club.name).join(", ");
  return b2`
    <button
      class="filter-chip team-pick ${picked.length ? "active" : ""}"
      aria-haspopup="dialog"
      title=${names || "Alla lag"}
      @click=${() => {
    ctx.ctl.picker = picker;
  }}
    >
      ${picked.length ? b2`<span class="crest-stack">
            ${picked.slice(0, 3).map(
    (club) => club.logo ? b2`<img src=${club.logo} alt="" loading="lazy" />` : b2`<span class="crest-blank"></span>`
  )}
          </span>` : b2`<ha-icon icon="mdi:shield-outline"></ha-icon>`}
      <span class="team-pick-label">
        ${!picked.length ? "Alla lag" : picked.length <= 2 ? names : `${picked.length} lag`}
      </span>
      <ha-icon icon="mdi:chevron-down"></ha-icon>
    </button>
  `;
}

// src/views/scroll.ts
function scrollToNext(view) {
  let row = view.querySelector(".fixture-row.next");
  if (row?.previousElementSibling?.classList.contains("team-section")) {
    row = row.previousElementSibling;
  }
  const panel = view.closest(".panel");
  if (!row || !panel) return false;
  panel.scrollTop = row.offsetTop - panel.offsetTop - 8;
  return true;
}
async function toTop(view, settled) {
  await settled;
  const panel = view.closest(".panel");
  if (panel) panel.scrollTop = 0;
}

// src/views/schedule.ts
var HockeyScheduleView = class extends PartElement {
  updated() {
    if (this.ctx.ctl.schedule?.scrollToNext && scrollToNext(this)) {
      this.ctx.ctl.scrolledToNext("schedule");
    }
  }
  // The clubs to choose from, along the foot of the list: everybody's games,
  // or the games of the clubs chosen.
  bar() {
    const { ctl } = this.ctx;
    const clubs = ctl.scheduleClubs();
    if (!clubs.length) return A;
    return filterBar(teamButton(this.ctx, "schedule", clubs, ctl.schedule?.teams ?? []));
  }
  dayLabel(when) {
    const { locale } = this.ctx;
    if (Number.isNaN(when.getTime())) return "";
    return relativeDay(when, locale) ?? when.toLocaleDateString(locale, { weekday: "long", day: "numeric", month: "long" });
  }
  render() {
    const { ctx } = this;
    const { loading: busy, error, nextIndex, teams = [] } = ctx.ctl.schedule ?? {};
    if (busy) return loading("H\xE4mtar spelschema\u2026");
    if (error) return b2`<div class="recap-note">${error}</div>`;
    const wanted = new Set(teams);
    const games = (ctx.ctl.schedule?.games ?? []).map((game, index) => ({ game, index })).filter(
      ({ game }) => !wanted.size || wanted.has(clubKey(game.home_code)) || wanted.has(clubKey(game.away_code))
    );
    const next = nextIndex == null ? null : games.find(({ index }) => index >= nextIndex)?.index ?? null;
    if (!games.length) {
      return b2`<div class="recap-note">
          ${wanted.size ? "Inga matcher f\xF6r de valda lagen." : "Inga matcher i schemat."}
        </div>
        ${this.bar()}`;
    }
    const rows2 = [];
    let day = null;
    for (const { game, index } of games) {
      const when = new Date(game.start);
      const stamp = Number.isNaN(when.getTime()) ? "" : when.toDateString();
      if (stamp !== day) {
        day = stamp;
        rows2.push(b2`<div class="team-section">${this.dayLabel(when)}</div>`);
      }
      rows2.push(fixtureRow(ctx, game, null, { isNext: index === next, hideDate: true, markSelf: true }));
    }
    rows2.push(this.bar());
    return rows2;
  }
};

// src/parts/stats.ts
function statsLogo(ctx, code, data) {
  const key = clubKey(code);
  const row = (data?.teams ?? []).find((team) => clubKey(team.team_code) === key);
  return row?.logo ?? ctx.ctl.crestOf(code);
}
function statsCrest(ctx, code, data, cls) {
  const logo = statsLogo(ctx, code, data);
  return logo ? b2`<img class=${cls} src=${logo} alt="" loading="lazy" />` : b2`<span class=${cls}></span>`;
}
function statsWho(ctx, kind, row) {
  if (kind === "teams") {
    const open = (ev) => {
      ev.stopPropagation();
      ctx.ctl.openTeamByCode(row.team_code, row.team, row.logo, "stats");
    };
    return b2`<span
      class="player-link"
      role="button"
      tabindex="0"
      @click=${open}
      @keydown=${onActivate(open)}
      >${row.team ?? row.team_code}</span
    >`;
  }
  return playerLink(
    ctx,
    row.player,
    row.team_code,
    b2`<span class="full-name">${row.player}</span><span class="short-name"
        >${shortName(row.player)}</span
      >`
  );
}
function placeClass(place, count) {
  if (!place || !count) return "";
  if (place <= Math.max(1, Math.round(count / 4))) return "top";
  if (place > count - Math.max(1, Math.round(count / 4))) return "bottom";
  return "";
}

// src/views/stats.ts
var HockeyStatsView = class extends PartElement {
  render() {
    const { ctl } = this.ctx;
    const scope = ctl.statsScope();
    const { data, loading: busy, error } = ctl.statsData?.[scope] ?? {};
    const section = ctl.stats?.section ?? "leaders";
    let body;
    if (!data) {
      body = busy || !error ? loading("H\xE4mtar statistiken\u2026", section === "leaders" ? "cards" : "table") : b2`<div class="recap-note">${error}</div>`;
    } else if (section === "leaders") {
      body = this.leaders(data);
    } else {
      body = this.table(section, data);
    }
    return b2`
      <div class="switch st-sections">
        ${STATS_SECTIONS.map(
      ([id, label]) => b2`
            <button
              class=${section === id ? "active" : ""}
              aria-pressed=${section === id ? "true" : "false"}
              @click=${() => {
        ctl.setStats({ section: id, more: STATS_PAGE });
        toTop(this, ctl.settled());
      }}
            >
              ${label}
            </button>
          `
    )}
      </div>
      ${error && data ? b2`<div class="recap-note">${error}</div>` : A}
      ${body} ${this.foot(data)} ${this.bar(section, data, Boolean(busy && data))}
    `;
  }
  // When the figures were read, and where the league keeps the rest.
  foot(data) {
    const { locale, hass } = this.ctx;
    const updated = data?.updated ? new Date(data.updated) : null;
    const time = updated && !Number.isNaN(updated.getTime()) ? updated.toLocaleTimeString(locale, timeFormat(hass)) : null;
    if (!time && !data?.stats_url) return A;
    return b2`
      <div class="st-foot">
        ${time ? b2`<span>Uppdaterad ${time}</span>` : A}
        ${data?.stats_url ? b2`<a class="st-source" href=${data.stats_url} target="_blank" rel="noopener noreferrer"
              >Mer statistik hos ligan
              <ha-icon icon="mdi:open-in-new"></ha-icon
            ></a>` : A}
      </div>
    `;
  }
  // Which games the figures cover, for every section; and for the lists of
  // players, which clubs and - for skaters - which position. A league that
  // cannot be asked for the last few games says so in its answer, and from
  // then on the choice is not offered. A stale copy being read again runs
  // the row's busy line rather than hiding what is on show.
  bar(section, data, busy) {
    const { ctx } = this;
    const { ctl } = ctx;
    const scope = ctl.statsScope();
    const known = Object.values(ctl.statsData ?? {}).find((entry) => entry?.data)?.data;
    const scopes = STATS_SCOPES.filter(
      (s4) => !s4.needs || known?.scopes?.[s4.needs] !== false || s4.id === scope
    );
    const filters = ctl.stats?.filters?.[section] ?? {};
    const players = section === "skaters" || section === "goalies";
    const positions = section === "skaters" && (data?.skaters ?? []).some((row) => positionOf(row).group !== "other");
    return filterBar(
      b2`
        ${filterSelect(
        "Vilka matcher statistiken g\xE4ller",
        scope,
        scopes.map((s4) => [s4.id, s4.label, s4.short]),
        (value) => {
          ctl.setStats({ scope: value, more: STATS_PAGE });
          ctl.loadStats(value);
        }
      )}
        ${players && data?.teams?.length ? teamButton(ctx, section, ctl.clubsOf(data.teams), filters.teams ?? []) : A}
        ${positions ? filterSelect(
        "Position",
        filters.position ?? "",
        POSITION_FILTERS,
        (value) => ctl.setStatsFilter(section, { position: value || null })
      ) : A}
      `,
      busy
    );
  }
  // ---- Leaders --------------------------------------------------------------
  // The followed club first, as the league sees it; then a row of cards for
  // each kind, the best five at each figure, a swipe along to the next.
  leaders(data) {
    return b2`
      ${this.ours(data)}
      ${Object.entries(STATS_LEADERS).map(([kind, keys]) => {
      const cards = keys.map((key) => this.leaderCard(kind, key, data)).filter((card2) => card2 !== A);
      if (!cards.length) return A;
      return b2`
          <div class="lb-head">
            <span class="team-section">${STATS_KINDS[kind].label}</span>
            <span class="lb-arrows">
              <button
                class="lb-arrow"
                aria-label="Bläddra bakåt"
                @click=${(ev) => this.scrollLeaders(ev, -1)}
              >
                <ha-icon icon="mdi:chevron-left"></ha-icon>
              </button>
              <button
                class="lb-arrow"
                aria-label="Bläddra framåt"
                @click=${(ev) => this.scrollLeaders(ev, 1)}
              >
                <ha-icon icon="mdi:chevron-right"></ha-icon>
              </button>
            </span>
          </div>
          <div class="lb-track">${cards}</div>
        `;
    })}
    `;
  }
  scrollLeaders(ev, step) {
    const track = ev.currentTarget.closest(".lb-head")?.nextElementSibling;
    if (!track) return;
    const card2 = track.querySelector(".lb-card");
    const width = card2 ? card2.getBoundingClientRect().width + 10 : track.clientWidth * 0.8;
    track.scrollBy({ left: step * width, behavior: "smooth" });
  }
  leaderCard(kind, key, data) {
    const { ctx } = this;
    const metric = STATS_KINDS[kind].metrics[key];
    const { ranked } = rankStats(data?.[kind], key, metric);
    if (!ranked.length) return A;
    const ours = clubKey(ctx.ctl.teamRef());
    const [first, ...rest] = ranked.slice(0, 5);
    const self = (row) => clubKey(row.team_code) === ours ? "self" : "";
    return b2`
      <div class="lb-card">
        <button class="lb-title" @click=${() => this.openTable(kind, key)}>
          <span>${metric.label}</span>
          <ha-icon icon="mdi:chevron-right"></ha-icon>
        </button>
        <div class="lb-top ${self(first.row)}">
          ${kind !== "teams" && first.row.photo ? b2`<img
                class="lb-photo"
                src=${first.row.photo}
                alt=""
                loading="lazy"
                style=${`--club: ${ctx.ctl.clubColourOf(first.row.team_code)}`}
              />` : statsCrest(ctx, first.row.team_code, data, "lb-photo crest")}
          <span class="lb-top-text">
            <span class="lb-top-name">${statsWho(ctx, kind, first.row)}</span>
            <span class="lb-top-team">
              ${kind === "teams" ? `${first.row.GP ?? ""} matcher` : b2`${statsCrest(ctx, first.row.team_code, data, "lb-mini")}${first.row.team ?? first.row.team_code}`}
            </span>
          </span>
          <span class="lb-top-value"
            >${formatStat(first.row[key], metric.kind)}${metric.kind === "pct" ? b2`<span class="lb-unit">%</span>` : A}</span
          >
        </div>
        ${rest.map(
      ({ row, rank }) => b2`
            <div class="lb-row ${self(row)}">
              <span class="lb-rank">${rank}</span>
              ${statsCrest(ctx, row.team_code, data, "lb-crest")}
              <span class="lb-name">${statsWho(ctx, kind, row)}</span>
              <span class="lb-value">${formatStat(row[key], metric.kind, true)}</span>
            </div>
          `
    )}
      </div>
    `;
  }
  // The followed club as the league sees it: where it stands at the figures
  // that say most about a team, and its best player's place among everyone.
  ours(data) {
    const { ctx } = this;
    const key = clubKey(ctx.ctl.teamRef());
    const teams = data?.teams ?? [];
    const row = teams.find((team) => clubKey(team.team_code) === key);
    if (!row) return A;
    const tiles = ["PP_perc", "PK_perc", "GF_GP", "GA_GP", "SVS_perc", "FO_perc"].filter((s4) => row[s4] !== void 0 && row[s4] !== null).map((s4) => {
      const metric = TEAM_METRICS[s4];
      const place = rankStats(teams, s4, metric).ranked.find((r4) => r4.row === row)?.rank;
      return { stat: s4, metric, place };
    });
    const scorer = rankStats(data?.skaters, "TP", SKATER_METRICS.TP).ranked.find(
      ({ row: player }) => clubKey(player.team_code) === key
    );
    const open = () => ctx.ctl.openTeamByCode(row.team_code, row.team, row.logo, "stats");
    return b2`
      <div
        class="st-ours tappable"
        role="button"
        tabindex="0"
        style=${`--club: ${ctx.ctl.clubColourOf(row.team_code)}`}
        @click=${open}
        @keydown=${onActivate(open)}
      >
        ${badge(row.logo, "hero-bg")}
        <div class="st-ours-head">
          ${badge(row.logo, "st-ours-crest")}
          <span class="st-ours-title">${row.team ?? row.team_code} i ligan</span>
          <ha-icon icon="mdi:chevron-right"></ha-icon>
        </div>
        <div class="st-ours-tiles">
          ${tiles.map(
      ({ stat: stat2, metric, place }) => b2`
              <span class="st-ours-tile">
                <span class="st-ours-value">${formatStat(row[stat2], metric.kind, true)}</span>
                <span class="st-ours-label">${metric.short}</span>
                ${place ? b2`<span class="st-place ${placeClass(place, teams.length)}"
                      >${ordinal(place)}</span
                    >` : A}
              </span>
            `
    )}
        </div>
        ${scorer ? b2`<div class="st-ours-foot">
              Bäst i laget: ${scorer.row.player}, ${scorer.row.TP} poäng –
              ${ordinal(scorer.rank)} i ligan
            </div>` : A}
      </div>
    `;
  }
  // ---- Tables ---------------------------------------------------------------
  // From a leader card into the whole list, sorted on what the card was for
  // and with the columns that figure is in.
  openTable(kind, key) {
    const { ctl } = this.ctx;
    const groups = STATS_COLUMNS[kind];
    const group = groups.find((g2) => g2.columns.includes(key)) ?? groups[0];
    ctl.setStats({
      section: kind,
      groups: { ...ctl.stats?.groups ?? {}, [kind]: group.id },
      sorts: { ...ctl.stats?.sorts ?? {}, [kind]: { key } },
      more: STATS_PAGE
    });
    toTop(this, ctl.settled());
  }
  table(kind, data) {
    const { ctx } = this;
    const { ctl } = ctx;
    const metrics = STATS_KINDS[kind].metrics;
    const all = kind === "teams" ? withSquads(data?.teams, ctl.squads?.data) : data?.[kind] ?? [];
    const has = (key2) => all.some((row) => row[key2] !== void 0 && row[key2] !== null);
    const groups = STATS_COLUMNS[kind].map((group2) => ({ ...group2, columns: group2.columns.filter(has) })).filter((group2) => group2.columns.length);
    if (!all.length || !groups.length) {
      return b2`<div class="recap-note">Ingen statistik.</div>`;
    }
    const group = groups.find((g2) => g2.id === ctl.stats?.groups?.[kind]) ?? groups[0];
    const { columns } = group;
    const asked = ctl.stats?.sorts?.[kind];
    const key = asked && columns.includes(asked.key) ? asked.key : columns.includes(group.sort) ? group.sort : columns[0];
    const metric = metrics[key] ?? {};
    const natural = metric.dir ?? "desc";
    const dir = asked?.key === key && asked.dir ? asked.dir : natural;
    const filters = ctl.stats?.filters?.[kind] ?? {};
    const teams = new Set(filters.teams ?? []);
    const keep = (row) => (!teams.size || teams.has(clubKey(row.team_code))) && (!filters.position || positionOf(row).group === filters.position);
    const league = rankStats(all, key, metric, natural);
    const ranked = league.ranked.filter(({ row }) => keep(row));
    const rest = league.rest.filter(({ row }) => keep(row));
    const missing = all.filter((row) => keep(row) && statNumber(row[key]) === null).map((row) => ({ row, rank: null }));
    let list = [...ranked, ...rest];
    if (dir !== natural) list = [...ranked].reverse().concat([...rest].reverse());
    list = list.concat(missing);
    const limit = ctl.stats?.more ?? STATS_PAGE;
    const shown = list.slice(0, limit);
    const firstShort = rest.length ? ranked.length : -1;
    const ours = teams.size === 1 ? null : clubKey(ctl.teamRef());
    const width = (k2) => ({ time: "3.2em", pct: "3.2em", dec: "3em", dec1: "3em", crowd: "3.8em" })[metrics[k2]?.kind ?? ""] ?? "2.4em";
    const grid = `grid-template-columns: 1.7em minmax(0, 1fr) ${columns.map(width).join(" ")}`;
    const sortBy = (column) => {
      const columnNatural = metrics[column]?.dir ?? "desc";
      const next = column === key ? dir === "asc" ? "desc" : "asc" : columnNatural;
      ctl.setStats({
        sorts: { ...ctl.stats?.sorts ?? {}, [kind]: { key: column, dir: next } }
      });
    };
    return b2`
      ${groups.length > 1 ? b2`<div class="st-groups" role="toolbar" aria-label="Kolumner">
            ${groups.map(
      (g2) => b2`
                <button
                  class="filter-chip ${g2.id === group.id ? "active" : ""}"
                  aria-pressed=${g2.id === group.id ? "true" : "false"}
                  @click=${() => ctl.setStats({
        groups: { ...ctl.stats?.groups ?? {}, [kind]: g2.id }
      })}
                >
                  ${g2.label}
                </button>
              `
    )}
          </div>` : A}
      <div class="st-table">
        <div class="st-row head" style=${grid}>
          <span>#</span>
          <span>${kind === "teams" ? "Lag" : kind === "goalies" ? "M\xE5lvakt" : "Spelare"}</span>
          ${columns.map(
      (column) => b2`
              <span
                class="roster-sort ${column === key ? "active" : ""}"
                role="button"
                tabindex="0"
                title=${metrics[column]?.label ?? column}
                @click=${() => sortBy(column)}
                @keydown=${onActivate(() => sortBy(column))}
                >${metrics[column]?.short ?? column}${column === key ? b2`<span class="st-arrow">${dir === "asc" ? "\u25B2" : "\u25BC"}</span>` : A}</span
              >
            `
    )}
        </div>
        ${shown.map(
      ({ row, rank }, index) => b2`
            ${index === firstShort && dir === natural ? b2`<div class="st-short">
                  Under ligans gräns för att rankas i ${(metric.label ?? "").toLowerCase()}
                </div>` : A}
            <div
              class="st-row ${clubKey(row.team_code) === ours ? "self" : ""} ${rank === null ? "unranked" : ""}"
              style=${grid}
            >
              <span class="st-rank">${rank ?? ""}</span>
              <span class="st-name">
                ${statsCrest(ctx, row.team_code, data, "st-crest")} ${statsWho(ctx, kind, row)}
              </span>
              ${columns.map(
        (column) => b2`<span class=${column === key ? "sorted" : ""}
                  >${formatStat(row[column], metrics[column]?.kind)}</span
                >`
      )}
            </div>
          `
    )}
      </div>
      ${list.length ? A : b2`<div class="recap-note">Ingen i urvalet.</div>`}
      ${list.length > shown.length ? b2`<button
            class="stats-more st-more"
            @click=${() => ctl.setStats({ more: limit + STATS_PAGE * 2 })}
          >
            Visa fler (${list.length - shown.length} till)
            <ha-icon icon="mdi:chevron-down"></ha-icon>
          </button>` : A}
      <div class="st-legend">
        ${columns.map((column) => `${metrics[column]?.short} ${metrics[column]?.label}`).join(" \xB7 ")}
      </div>
    `;
  }
};

// src/parts/standings.ts
function tableRows(ctx, table, live = false) {
  return b2`
    <div class="table">
      <div class="table-row head">
        <span>#</span><span>Lag</span><span>M</span><span>+/-</span><span>P</span>
        <span class="table-form">Form</span>
      </div>
      ${(table ?? []).map((r4) => {
    const open = () => ctx.ctl.openTeam(r4);
    return b2`
          <div
            class="table-row tappable ${r4.is_self ? "self" : ""} ${isCut(r4.rank) ? "cut" : ""} zone-${zoneOf(r4.rank) ?? "none"}"
            role="button"
            tabindex="0"
            @click=${open}
            @keydown=${onActivate(open)}
          >
            <span class="table-rank">
              ${r4.rank ?? ""}${live ? move(r4.rank_change) : A}
            </span>
            <span class="table-team">
              ${r4.logo ? b2`<img class="table-logo" src=${r4.logo} alt="" loading="lazy" />` : b2`<span class="table-logo"></span>`}
              <span class="table-name">${r4.team ?? r4.team_code}</span>
              ${live && r4.live ? b2`<span class="playing" title="Spelar nu"></span>` : A}
            </span>
            <span>${r4.games_played ?? ""}</span>
            <span>${plus(r4.goal_difference)}</span>
            <span class="table-points">${r4.points ?? ""}</span>
            <span class="table-form">${form(ctx, r4.form)}</span>
          </div>
        `;
  })}
    </div>
  `;
}

// src/views/table.ts
var HockeyTableView = class extends PartElement {
  // The live table counts whatever is being played right now into the
  // official one. It only exists while a game is on, and the toggle with it.
  // Which of the two tables is being shown: the live one whenever there is
  // one, unless it has been switched off in the filter row.
  liveOn(liveTable) {
    return liveTable != null && this.ctx.ctl.liveTable !== false;
  }
  render() {
    const { ctx } = this;
    const { ctl, sources } = ctx;
    const { table, liveTable } = sources;
    const live = this.liveOn(liveTable);
    return b2`
      ${ctl.trend?.last ? this.trend() : tableRows(ctx, live ? liveTable : table, live)}
      ${filterBar(b2`
        ${filterSelect(
      "Tabellens omfattning",
      String(ctl.trend?.last ?? 0),
      TABLE_PERIODS,
      (value) => ctl.loadTrend(Number(value))
    )}
        ${liveTable != null && !ctl.trend?.last ? this.liveToggle(liveTable) : A}
      `)}
    `;
  }
  trend() {
    const { loading: busy, error, table } = this.ctx.ctl.trend ?? {};
    if (busy) return loading("R\xE4knar formtabell\u2026", "table");
    if (error) return b2`<div class="recap-note">${error}</div>`;
    if (!table?.length) return b2`<div class="recap-note">Inga spelade matcher.</div>`;
    return tableRows(this.ctx, table);
  }
  // The live/official switch sits beside the period in the filter row, out
  // of the way of the standings themselves.
  liveToggle(liveTable) {
    const live = this.liveOn(liveTable);
    return b2`
      <button
        class="filter-chip live-chip ${live ? "active" : ""}"
        aria-pressed=${live ? "true" : "false"}
        title=${live ? "Med p\xE5g\xE5ende matcher" : "Officiella tabellen"}
        @click=${() => {
      this.ctx.ctl.liveTable = !live;
    }}
      >
        <span class="live-dot"></span>Live
      </button>
    `;
  }
};

// src/views/team.ts
var SQUAD_FIGURES = [
  ["height", "Snittl\xE4ngd", "cm"],
  ["weight", "Snittvikt", "kg"],
  ["age", "Snitt\xE5lder", "\xE5r"]
];
var SQUAD_GROUPS = [
  ["gk", "M\xE5lvakter"],
  ["d", "Backar"],
  ["f", "Forwards"]
];
var SQUAD_ENDS = [
  ["tallest", "L\xE4ngst", "cm"],
  ["shortest", "Kortast", "cm"],
  ["heaviest", "Tyngst", "kg"],
  ["lightest", "L\xE4ttast", "kg"],
  ["oldest", "\xC4ldst", "\xE5r"],
  ["youngest", "Yngst", "\xE5r"]
];
var decimal2 = (value, digits = 1) => typeof value === "number" && Number.isFinite(value) ? value.toFixed(digits).replace(".", ",") : "\u2013";
var HockeyTeamView = class extends PartElement {
  updated() {
    const team = this.ctx.ctl.team;
    if (team?.scrollToNext && team.tab === "schedule" && scrollToNext(this)) {
      this.ctx.ctl.scrolledToNext("team");
    }
  }
  render() {
    const { ctx } = this;
    const { ctl, config } = ctx;
    const team = ctl.team ?? {};
    const { row, error } = team;
    const tab = team.tab ?? "overview";
    const back = b2`
      <button class="recap-back" @click=${() => ctl.closeTeam()}>
        <ha-icon icon="mdi:chevron-left"></ha-icon>${ctl.tableView === "live" ? "Matcher" : ctl.tableView === "schedule" ? "Spelschema" : ctl.tableView === "stats" ? "Statistik" : "Tabell"}
      </button>
    `;
    const record = row.wins != null && row.losses != null ? [row.wins, row.overtime_wins ?? 0, row.overtime_losses ?? 0, row.losses].join("\u2013") : null;
    const goals = row.goals_for != null && row.goals_against != null ? `${row.goals_for}\u2013${row.goals_against}` : null;
    return b2`
      ${back}
      <div class="hero" style=${`--club: ${ctl.clubColourOf(row.team_code)}`}>
        ${badge(row.logo, "hero-bg")}
        <div class="hero-main">
          ${badge(row.logo, "hero-crest")}
          <div class="hero-titles">
            ${row.rank ? b2`<span class="hero-kicker as-written">${row.rank}:a i tabellen</span>` : A}
            <span class="hero-title">${row.team ?? row.team_code}</span>
            ${row.form?.length ? b2`<span class="hero-form" title="Senaste matcherna">${form(ctx, row.form)}</span>` : A}
          </div>
          ${row.points != null ? b2`<div class="hero-big">
                <span class="hero-big-value">${row.points}</span>
                <span class="hero-big-label">poäng</span>
              </div>` : A}
        </div>
        <div class="hero-stats">
          ${stat("Matcher", row.games_played)} ${stat("V\u2013\xD6V\u2013\xD6F\u2013F", record)} ${stat("M\xE5l", goals)}
          ${stat("M\xE5lskillnad", plus(row.goal_difference))}
        </div>
      </div>

      <div class="switch team-tabs">
        ${[
      ["overview", "\xD6versikt"],
      ["schedule", "Spelschema"],
      ["roster", "Trupp"],
      config.show_stats !== false && ["stats", "Statistik"],
      ["news", "Nyheter"]
    ].filter(Boolean).map(
      ([id, label]) => b2`
            <button
              class=${tab === id ? "active" : ""}
              aria-pressed=${tab === id ? "true" : "false"}
              @click=${() => ctl.openTeamTab(id)}
            >
              ${label}
            </button>
          `
    )}
      </div>

      ${error ? b2`<div class="recap-note">${error}</div>` : A}
      ${tab === "overview" ? this.overview(team) : A}
      ${tab === "schedule" ? this.schedule(team) : A}
      ${tab === "roster" ? this.roster(team) : A}
      ${tab === "stats" ? this.stats(team) : A}
      ${tab === "news" ? this.news(team) : A}
    `;
  }
  overview(team) {
    const { row, next, results, loading: busy } = team;
    if (busy) return loading("H\xE4mtar laget\u2026");
    return b2`
      ${next?.length ? b2`
            <div class="team-section">Nästa matcher</div>
            ${next.map((game) => fixtureRow(this.ctx, game, row.team_code))}
          ` : A}
      ${results?.length ? b2`
            <div class="team-section">Senaste matcher</div>
            ${results.map((game) => fixtureRow(this.ctx, game, row.team_code))}
          ` : A}
    `;
  }
  schedule(team) {
    const { row, season, seasonLoading, seasonError, nextIndex, seasonBefore } = team;
    if (seasonLoading) return loading("H\xE4mtar spelschemat\u2026", "games");
    if (seasonError) return b2`<div class="recap-note">${seasonError}</div>`;
    if (!season?.length) return b2`<div class="recap-note">Inget spelschema.</div>`;
    return [
      seasonBefore ? A : b2`
            <button class="schedule-back" @click=${() => this.ctx.ctl.loadTeamSeason(200)}>
              ▲ Visa tidigare matcher
            </button>
          `,
      ...season.map(
        (game, index) => fixtureRow(this.ctx, game, row.team_code, { isNext: index === nextIndex })
      )
    ];
  }
  // ---- News -------------------------------------------------------------------
  // What the club's own site and the papers have written, newest first. Each
  // opens where it was published; the integration only knows the headline.
  news(team) {
    const { locale, hass } = this.ctx;
    const { news, newsLoading, newsError } = team;
    if (newsLoading) return loading("H\xE4mtar nyheterna\u2026", "table");
    if (newsError) return b2`<div class="recap-note">${newsError}</div>`;
    if (!news?.length) return b2`<div class="recap-note">Inga nyheter den senaste månaden.</div>`;
    return b2`
      ${news.map(
      (item) => b2`
          <a class="news-row" href=${item.url} target="_blank" rel="noopener noreferrer">
            <span class="news-title">${item.title}</span>
            <span class="news-meta"
              >${[item.source, newsWhen(item.published, locale, timeFormat(hass))].filter(Boolean).join(" \xB7 ")}</span
            >
          </a>
        `
    )}
      <div class="pv-source">Från klubbens sajt och tidningarna, via Google News</div>
    `;
  }
  // ---- The squad --------------------------------------------------------------
  // The squad in figures goes above the list, and stays when the list is
  // not to be had: the SHL publishes no player statistics, but its squads
  // can still be measured.
  roster(team) {
    return b2`${this.squad(team.row?.team_code)}${this.rosterList(team)}`;
  }
  rosterList(team) {
    const { ctl } = this.ctx;
    const { row, roster, rosterLoading, rosterError } = team;
    if (rosterLoading) return loading("H\xE4mtar truppen\u2026", "table");
    if (rosterError) return b2`<div class="recap-note">${rosterError}</div>`;
    if (!roster?.length) return b2`<div class="recap-note">Ingen trupp.</div>`;
    const grouped = team.group === true;
    const groups = grouped ? POSITION_GROUPS.map((group) => ({
      ...group,
      players: roster.filter((player) => positionOf(player).group === group.id)
    })).filter((group) => group.players.length) : [{ id: "all", label: null, players: roster }];
    return b2`
      <div class="switch">
        <button
          class=${grouped ? "" : "active"}
          aria-pressed=${grouped ? "false" : "true"}
          @click=${() => ctl.setTeam({ group: false })}
        >
          Hela truppen
        </button>
        <button
          class=${grouped ? "active" : ""}
          aria-pressed=${grouped ? "true" : "false"}
          @click=${() => ctl.setTeam({ group: true })}
        >
          Per position
        </button>
      </div>
      ${groups.map((group) => this.rosterTable(team, group, row.team_code))}
    `;
  }
  // ---- The squad in figures ------------------------------------------------------
  // Height, weight and age against the other clubs: a place, and a bar from
  // the league's lowest to its highest with the league's average marked.
  // First is the tallest, heaviest or oldest, which is neither good nor bad,
  // so the places are not coloured as the statistics' are.
  squad(code) {
    const { data, loading: busy } = this.ctx.ctl.squads ?? {};
    if (!data) return busy ? loading("M\xE4ter truppen\u2026", "table") : A;
    const teams = data.teams ?? [];
    const ours = teams.find((t3) => clubKey(t3.team_code) === clubKey(code));
    if (!ours?.players) return A;
    const league = data.league ?? {};
    const colour = this.ctx.ctl.clubColourOf(code);
    const { left = 0, right = 0 } = ours.shoots ?? {};
    const unknown = ours.players - left - right;
    return b2`
      <div class="team-section">Truppen i siffror</div>
      ${SQUAD_FIGURES.map(
      ([key, label, unit]) => this.squadRow(teams, ours, league, key, label, unit, colour)
    )}
      <div class="sq-table">
        <span class="sq-head"></span>
        <span class="sq-head">Antal</span>
        ${SQUAD_FIGURES.map(([, , unit]) => b2`<span class="sq-head">${unit}</span>`)}
        ${SQUAD_GROUPS.map(([key, label]) => {
      const group = ours.positions?.[key];
      if (!group?.players) return A;
      const theirs = league.positions?.[key] ?? {};
      return b2`
            <span class="sq-label">${label}</span>
            <span>${group.players}</span>
            ${SQUAD_FIGURES.map(
        ([figure, name, unit]) => b2`<span title=${`${name} i serien: ${decimal2(theirs[figure])} ${unit}`}
                  >${decimal2(group[figure])}</span
                >`
      )}
          `;
    })}
      </div>
      <div class="ts-leaders">
        <div class="ts-board">
          <span class="ts-board-title">Ytterligheter</span>
          ${SQUAD_ENDS.map(([key, label, unit]) => {
      const end = ours[key];
      if (!end?.player) return A;
      return b2`
              <span class="ts-board-row">
                <span class="lb-name"
                  ><span class="sq-end">${label}</span> ${playerLink(
        this.ctx,
        end.player,
        ours.team_code
      )}</span
                >
                <span class="lb-value"
                  >${unit === "\xE5r" ? decimal2(end.value) : end.value} ${unit}</span
                >
              </span>
            `;
    })}
        </div>
        <div class="ts-board">
          <span class="ts-board-title">Ursprung</span>
          ${(ours.countries ?? []).map(
      (country) => b2`
              <span class="ts-board-row">
                <span class="lb-name">${country.name ?? country.country}</span>
                <span class="lb-value">${country.players}</span>
              </span>
            `
    )}
          <span class="ts-board-title sq-subtitle">Fattning</span>
          <span class="ts-board-row">
            <span class="lb-name">Vänster</span><span class="lb-value">${left}</span>
          </span>
          <span class="ts-board-row">
            <span class="lb-name">Höger</span><span class="lb-value">${right}</span>
          </span>
          ${unknown > 0 ? b2`<span class="ts-board-row sq-unknown">
                <span class="lb-name">Okänd</span><span class="lb-value">${unknown}</span>
              </span>` : A}
        </div>
      </div>
    `;
  }
  squadRow(teams, ours, league, key, label, unit, colour) {
    const value = ours[key];
    if (typeof value !== "number") return A;
    const values = teams.map((t3) => t3[key]).filter((v2) => typeof v2 === "number");
    const low = Math.min(...values);
    const span = Math.max(...values) - low;
    const along = (v2) => span ? Math.min(1, Math.max(0, (v2 - low) / span)) : 1;
    const mean = typeof league[key] === "number" ? league[key] : null;
    const place = ours.ranks?.[key];
    return b2`
      <div class="ts-row" title=${`Serien: ${decimal2(mean)} ${unit}`}>
        <span class="ts-label">${label}</span>
        <span class="ts-value">${decimal2(value)} ${unit}</span>
        <span class="st-place">${place ? ordinal(place) : ""}</span>
        <span class="ts-track">
          <span
            class="ts-fill"
            style=${`width: ${(along(value) * 100).toFixed(1)}%; background: ${colour}`}
          ></span>
          ${mean !== null ? b2`<span class="ts-mean" style=${`left: ${(along(mean) * 100).toFixed(1)}%`}></span>` : A}
        </span>
      </div>
    `;
  }
  // Each table sorts on its own: what a goalkeeper is worth reading by is not
  // what a forward is.
  rosterTable(team, group, teamCode) {
    const { ctl } = this.ctx;
    const sort = team.sorts?.[group.id] ?? ROSTER_SORT;
    const goalies = group.id === "gk";
    const columns = goalies ? [
      ["player", "M\xE5lvakt"],
      ["GP", "M"],
      ["SVS_perc", "R\xE4dd%"],
      ["SO", "N"],
      ["GAA", "GAA"]
    ] : [
      ["player", "Spelare"],
      ["GP", "M"],
      ["G", "M\xE5l"],
      ["A", "A"],
      ["TP", "P"]
    ];
    return b2`
      ${group.label ? b2`<div class="team-section">${group.label}</div>` : A}
      <div class="roster-row head">
        ${columns.map(
      ([key, label]) => b2`
            <span
              class="roster-sort ${sort.key === key ? "active" : ""}"
              role="button"
              tabindex="0"
              @click=${() => ctl.sortRoster(group.id, key)}
              @keydown=${onActivate(() => ctl.sortRoster(group.id, key))}
              >${label}${sort.key === key ? sort.dir === "asc" ? " \u25B2" : " \u25BC" : ""}</span
            >
          `
    )}
      </div>
      ${this.sorted(group.players, sort, group.id !== "all").map(
      (player) => this.rosterRow(player, teamCode)
    )}
    `;
  }
  sorted(roster, sort, mixed = false) {
    const sign = sort.dir === "asc" ? 1 : -1;
    const byName = (a3, b3) => String(a3.player ?? "").localeCompare(String(b3.player ?? ""), "sv");
    const compare = (a3, b3) => sort.key === "player" ? sign * byName(a3, b3) : sign * (Number(a3[sort.key] ?? 0) - Number(b3[sort.key] ?? 0)) || byName(a3, b3);
    if (mixed) return [...roster].sort(compare);
    return [
      ...roster.filter((player) => player.role !== "goalkeeper").sort(compare),
      ...roster.filter((player) => player.role === "goalkeeper").sort(compare)
    ];
  }
  // A goalkeeper is on the same list, but points say nothing about one, so the
  // columns carry their save percentage instead.
  rosterRow(player, teamCode) {
    const goalie = player.role === "goalkeeper";
    const position = positionOf(player);
    return b2`
      <div class="roster-row">
        <span class="roster-name">
          ${player.photo ? b2`<img class="roster-photo" src=${player.photo} alt="" loading="lazy" />` : b2`<span class="roster-photo empty"></span>`}
          <span class="roster-position ${position.group}" title=${player.position ?? ""}>
            ${position.letter}
          </span>
          <span class="roster-number">${player.jersey ?? ""}</span>
          ${playerLink(this.ctx, player.player, teamCode)}
        </span>
        <span>${player.GP ?? ""}</span>
        ${goalie ? b2`<span class="roster-goalie">${player.SVS_perc ?? ""}%</span>
              <span>${player.SO ?? ""}</span>
              <span class="roster-points">${player.GAA ?? ""}</span>` : b2`<span>${player.G ?? ""}</span>
              <span>${player.A ?? ""}</span>
              <span class="roster-points">${player.TP ?? ""}</span>`}
      </div>
    `;
  }
  // ---- The club's statistics --------------------------------------------------
  // Each figure against the other clubs: its place, and a bar from the
  // league's worst to its best with the average marked. Always the season -
  // a club's page is about its season.
  stats(team) {
    const { ctl } = this.ctx;
    const { data, loading: busy, error } = ctl.statsData?.season ?? {};
    if (!data) {
      return busy || !error ? loading("H\xE4mtar statistiken\u2026", "table") : b2`<div class="recap-note">${error}</div>`;
    }
    const code = team.row?.team_code;
    const teams = data.teams ?? [];
    const row = teams.find((t3) => clubKey(t3.team_code) === clubKey(code));
    if (!row) return b2`<div class="recap-note">Ingen statistik för laget.</div>`;
    const colour = ctl.clubColourOf(code);
    return b2`
      ${TEAM_STAT_GROUPS.map((group) => {
      const keys = group.keys.filter(
        (key) => TEAM_METRICS[key] && row[key] !== void 0 && row[key] !== null
      );
      if (!keys.length) return A;
      return b2`
          <div class="team-section">${group.label}</div>
          ${keys.map((key) => this.statRow(teams, row, key, colour))}
        `;
    })}
      ${this.leaders(data, code)}
    `;
  }
  statRow(teams, row, key, colour) {
    const metric = TEAM_METRICS[key];
    const { ranked } = rankStats(teams, key, metric);
    const place = ranked.find((r4) => r4.row === row)?.rank;
    const values = ranked.map((r4) => statNumber(r4.row[key]));
    const value = statNumber(row[key]);
    const best = values[0];
    const worst = values[values.length - 1];
    const span = best - worst;
    const along = (v2) => span ? Math.min(1, Math.max(0, (v2 - worst) / span)) : 1;
    const mean = values.length ? values.reduce((sum, v2) => sum + v2, 0) / values.length : 0;
    return b2`
      <div
        class="ts-row"
        title=${`Ligasnitt ${formatStat(
      mean,
      metric.kind && ["pct", "dec", "crowd"].includes(metric.kind) ? metric.kind : "dec1",
      true
    )}`}
      >
        <span class="ts-label">${metric.label}</span>
        <span class="ts-value">${formatStat(row[key], metric.kind, true)}</span>
        <span class="st-place ${placeClass(place, teams.length)}"
          >${place ? ordinal(place) : ""}</span
        >
        <span class="ts-track">
          <span
            class="ts-fill"
            style=${`width: ${(along(value) * 100).toFixed(1)}%; background: ${colour}`}
          ></span>
          <span class="ts-mean" style=${`left: ${(along(mean) * 100).toFixed(1)}%`}></span>
        </span>
      </div>
    `;
  }
  // The club's own best at what a player is judged by, each with his place
  // among the whole league.
  leaders(data, code) {
    const key = clubKey(code);
    const boards = [
      ["skaters", "TP"],
      ["skaters", "G"],
      ["skaters", "A"],
      ["skaters", "PlusMinus"],
      ["skaters", "TOI_GP"],
      ["goalies", "SVS_perc"]
    ].map(([kind, s4]) => {
      const metric = STATS_KINDS[kind].metrics[s4];
      const { ranked, rest } = rankStats(data?.[kind], s4, metric);
      const ours = [...ranked, ...rest].filter(({ row }) => clubKey(row.team_code) === key).slice(0, 3);
      return ours.length ? { kind, stat: s4, metric, ours } : null;
    }).filter(Boolean);
    if (!boards.length) return A;
    return b2`
      <div class="team-section">Lagets bästa</div>
      <div class="ts-leaders">
        ${boards.map(
      ({ kind, stat: s4, metric, ours }) => b2`
            <div class="ts-board">
              <span class="ts-board-title">${metric.label}</span>
              ${ours.map(
        ({ row, rank }) => b2`
                  <span class="ts-board-row">
                    <span class="lb-name">${statsWho(this.ctx, kind, row)}</span>
                    <span class="lb-value">${formatStat(row[s4], metric.kind, true)}</span>
                    <span class="ts-board-place">${rank ? ordinal(rank) : "\u2013"}</span>
                  </span>
                `
      )}
            </div>
          `
    )}
      </div>
    `;
  }
};

// src/views/today.ts
var HockeyTodayView = class extends PartElement {
  constructor() {
    super(...arguments);
    this.swipe = null;
  }
  dayTitle(offset) {
    return dayTitle(this.ctx.ctl.dayDate(offset), offset, this.ctx.locale);
  }
  async step(step) {
    this.ctx.ctl.stepDay(step);
    await this.ctx.ctl.settled();
    this.querySelector(".day-body")?.animate?.(
      [
        { transform: `translateX(${step > 0 ? 40 : -40}px)`, opacity: 0 },
        { transform: "none", opacity: 1 }
      ],
      { duration: 200, easing: "ease-out" }
    );
  }
  render() {
    const { ctx } = this;
    const { ctl, locale, hass } = ctx;
    const offset = ctl.day ?? 0;
    const current = ctl.tonight?.day === offset ? ctl.tonight : {};
    const { games, loading: busy, error, updated } = current ?? {};
    const subtitle = Math.abs(offset) <= 1 ? ctl.dayDate(offset).toLocaleDateString(locale, { weekday: "long", ...DATE }) : null;
    const bar = b2`
      <div class="day-bar ${busy && games ? "busy" : ""}">
        <button class="day-step" aria-label="Föregående dag" @click=${() => this.step(-1)}>
          <ha-icon icon="mdi:chevron-left"></ha-icon>
        </button>
        <div class="day-title">
          <span>${this.dayTitle(offset)}</span>
          ${subtitle ? b2`<span class="day-sub">${subtitle}</span>` : A}
        </div>
        <button class="day-step" aria-label="Nästa dag" @click=${() => this.step(1)}>
          <ha-icon icon="mdi:chevron-right"></ha-icon>
        </button>
      </div>
    `;
    let body;
    if (busy && !games) body = loading("H\xE4mtar matcherna\u2026", "games");
    else if (error && !games) body = b2`<div class="recap-note">${error}</div>`;
    else if (!games?.length) body = b2`<div class="recap-note">Inga matcher den här dagen.</div>`;
    else {
      body = b2`
        ${games.map(
        (game) => fixtureRow(ctx, game, null, {
          hideDate: true,
          markSelf: true,
          live: offset === 0,
          ended: true
        })
      )}
        ${updated && offset === 0 ? b2`<div class="live-updated">
              Uppdaterad ${updated.toLocaleTimeString(locale, timeFormat(hass))}
            </div>` : A}
      `;
    }
    return b2`
      ${bar}
      <div
        class="day-body"
        @touchstart=${{ handleEvent: (ev) => this.swipeStart(ev), passive: true }}
        @touchmove=${{ handleEvent: (ev) => this.swipeMove(ev), passive: true }}
        @touchend=${(ev) => this.swipeEnd(ev)}
        @touchcancel=${(ev) => this.swipeEnd(ev, true)}
      >
        ${body}
      </div>
    `;
  }
  swipeStart(ev) {
    if (ev.touches.length !== 1) {
      this.swipe = null;
      return;
    }
    const t3 = ev.touches[0];
    this.swipe = { x: t3.clientX, y: t3.clientY, dx: 0, horizontal: null };
  }
  swipeMove(ev) {
    const swipe = this.swipe;
    if (!swipe) return;
    const t3 = ev.touches[0];
    const dx = t3.clientX - swipe.x;
    const dy = t3.clientY - swipe.y;
    if (swipe.horizontal === null) {
      if (Math.abs(dx) < 8 && Math.abs(dy) < 8) return;
      swipe.horizontal = Math.abs(dx) > Math.abs(dy) * 1.2;
    }
    if (!swipe.horizontal) return;
    swipe.dx = dx;
    const body = ev.currentTarget;
    body.style.transition = "none";
    body.style.transform = `translateX(${dx * 0.5}px)`;
    body.style.opacity = String(Math.max(0.4, 1 - Math.abs(dx) / 600));
  }
  swipeEnd(ev, cancelled = false) {
    const swipe = this.swipe;
    this.swipe = null;
    const body = ev.currentTarget;
    if (!swipe?.horizontal) return;
    const width = body.getBoundingClientRect().width || 300;
    const turn = !cancelled && Math.abs(swipe.dx) > Math.min(80, width * 0.22);
    if (turn) {
      body.style.transition = "";
      body.style.transform = "";
      body.style.opacity = "";
      this.step(swipe.dx < 0 ? 1 : -1);
      return;
    }
    body.style.transition = "transform 0.18s ease-out, opacity 0.18s ease-out";
    body.style.transform = "";
    body.style.opacity = "";
  }
};

